    use super::*;

    #[test]
    fn control_round_trip() {
        let mut pkt = Control::default();
        pkt._header = PacketHeader::default();
        pkt.reason = 0x0065u16;
        pkt.type = 0x03u8;
        pkt.timestamp = 0x0000000000002713u64;
        pkt.mono_ticks = 0x0000000000002714u64;

        let mut buf = [0u8; Control::SIZE];
        let written = pkt.serialize(&mut buf).expect("serialize failed");
        assert_eq!(written, Control::SIZE);

        let parsed = Control::deserialize(&buf).expect("deserialize failed");
        assert_eq!(pkt, parsed);
    }

